const TOUR_DATA=[{id:'evening',name:'Evening Desert Safari',type:'Safari',prices:[['Sharing',120],['Private',650]]},{id:'morning',name:'Morning Desert Safari',type:'Safari',prices:[['Private',550]]},{id:'premium',name:'Premium Desert Safari',type:'Premium',prices:[['Sharing',220],['Private',850]]},{id:'quad',name:'Quad Bike Adventure',type:'Adventure',prices:[['Per bike / 30 min',150]]},{id:'canam2',name:'Can-Am Buggy · 2 Seater',type:'Buggy',prices:[['2 seater / 30 min',1000]]},{id:'canam4',name:'Can-Am Buggy · 4 Seater',type:'Buggy',prices:[['4 seater / 30 min',1500]]}];const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let bookings=JSON.parse(localStorage.getItem('phoenixBookings')||'[]');let tours=JSON.parse(localStorage.getItem('phoenixAdminTours')||'null')||TOUR_DATA;function save(){localStorage.setItem('phoenixBookings',JSON.stringify(bookings));localStorage.setItem('phoenixAdminTours',JSON.stringify(tours))}function money(n){return `AED ${Number(n||0).toLocaleString()}`}function statusBadge(s){return `<span class="status ${s}">${s}</span>`}function todayDubai(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dubai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}function renderStats(){const today=todayDubai();$('#statToday').textContent=bookings.filter(b=>b.date===today).length;$('#statTotal').textContent=bookings.length;$('#statRevenue').textContent=money(bookings.filter(b=>b.status!=='Cancelled').reduce((a,b)=>a+Number(b.total||0),0));$('#statPending').textContent=bookings.filter(b=>b.status==='New').length}function row(b,actions=false){return `<tr><td><strong>${b.id}</strong></td><td>${b.name||'—'}<br><small>${b.phone||''}</small></td><td>${b.tour}<br><small>${b.package||''}</small></td><td>${b.date||'—'}</td>${actions?`<td>${b.quantity||1}</td>`:''}<td>${money(b.total)}</td><td>${statusBadge(b.status||'New')}</td>${actions?`<td><select data-status="${b.id}"><option${b.status==='New'?' selected':''}>New</option><option${b.status==='Confirmed'?' selected':''}>Confirmed</option><option${b.status==='Completed'?' selected':''}>Completed</option><option${b.status==='Cancelled'?' selected':''}>Cancelled</option></select></td>`:''}</tr>`}function renderRecent(){$('#recentRows').innerHTML=bookings.slice(0,6).map(b=>row(b)).join('')||'<tr><td colspan="6">No bookings yet.</td></tr>';const counts={};bookings.forEach(b=>counts[b.tour]=(counts[b.tour]||0)+1);const popular=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,5);$('#popularTours').innerHTML=popular.length?popular.map(([n,c])=>`<div class="popular-item"><strong>${n}</strong><span>${c} booking${c>1?'s':''}</span></div>`).join(''):'<div class="popular-item"><strong>No data yet</strong><span>Bookings will appear here</span></div>'}function renderBookings(){const q=$('#bookingSearch').value.trim().toLowerCase(),sf=$('#statusFilter').value;const list=bookings.filter(b=>(sf==='all'||b.status===sf)&&(!q||`${b.id} ${b.name} ${b.phone} ${b.tour}`.toLowerCase().includes(q)));$('#bookingRows').innerHTML=list.map(b=>row(b,true)).join('')||'<tr><td colspan="8">No matching bookings.</td></tr>';$$('[data-status]').forEach(s=>s.onchange=()=>{const b=bookings.find(x=>x.id===s.dataset.status);if(b){b.status=s.value;save();renderAll()}})}function renderTours(){$('#tourAdminGrid').innerHTML=tours.map((t,ti)=>`<article class="tour-admin-card"><small>${t.type}</small><h3>${t.name}</h3>${t.prices.map((p,pi)=>`<div class="price-row"><span>${p[0]}</span><label>AED <input type="number" min="0" value="${p[1]}" data-tour-price="${ti}:${pi}"></label></div>`).join('')}</article>`).join('');$$('[data-tour-price]').forEach(i=>i.onchange=()=>{const[ti,pi]=i.dataset.tourPrice.split(':').map(Number);tours[ti].prices[pi][1]=Number(i.value)||0;save()})}function renderAll(){renderStats();renderRecent();renderBookings();renderTours()}$$('.sidebar nav button').forEach(b=>b.onclick=()=>{$$('.sidebar nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');$$('.view').forEach(v=>v.classList.remove('active'));$('#'+b.dataset.view).classList.add('active');$('#viewTitle').textContent={overview:'Dashboard Overview',bookings:'Bookings',tours:'Tour Manager',settings:'Settings'}[b.dataset.view]});$$('[data-go]').forEach(b=>b.onclick=()=>document.querySelector(`.sidebar nav button[data-view="${b.dataset.go}"]`).click());$('#bookingSearch').oninput=renderBookings;$('#statusFilter').onchange=renderBookings;$('#exportBtn').onclick=()=>{if(!bookings.length)return alert('No bookings to export.');const heads=['ID','Created','Customer','Phone','Tour','Package','Quantity','Date','Time','Pickup','Total','Status'];const lines=[heads.join(','),...bookings.map(b=>[b.id,b.createdAt,b.name,b.phone,b.tour,b.package,b.quantity,b.date,b.time,b.pickup,b.total,b.status].map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(','))];const blob=new Blob([lines.join('\n')],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='phoenix-bookings.csv';a.click();URL.revokeObjectURL(a.href)};const dialog=$('#bookingDialog'),manualTour=$('#manualTour');manualTour.innerHTML=TOUR_DATA.map(t=>`<option>${t.name}</option>`).join('');$('#addBookingBtn').onclick=()=>dialog.showModal();$('#manualBookingForm').onsubmit=e=>{e.preventDefault();const b={id:`PX-${Date.now().toString().slice(-8)}`,createdAt:new Date().toISOString(),name:$('#manualName').value.trim(),phone:$('#manualPhone').value.trim(),tour:manualTour.value,package:'Manual booking',quantity:Number($('#manualQty').value)||1,date:$('#manualDate').value,time:'To confirm',pickup:'To confirm',total:Number($('#manualTotal').value)||0,status:'New'};bookings.unshift(b);save();renderAll();dialog.close();e.target.reset()};const settings=JSON.parse(localStorage.getItem('phoenixSettings')||'{}');if(settings.company)$('#settingCompany').value=settings.company;if(settings.phone)$('#settingPhone').value=settings.phone;if(settings.location)$('#settingLocation').value=settings.location;if(settings.payment)$('#settingPayment').value=settings.payment;$('#saveSettings').onclick=()=>{localStorage.setItem('phoenixSettings',JSON.stringify({company:$('#settingCompany').value,phone:$('#settingPhone').value,location:$('#settingLocation').value,payment:$('#settingPayment').value}));alert('Settings saved.')};renderAll();